    private fun oetf(x: Float) = if (x <= 0.0031308f) 12.92f * x else (1.055 * Math.pow(x.toDouble(), 1 / 2.4) - 0.055).toFloat()

    @Test fun matchesDctlReferenceForEveryPreset() {
        for (c in cases) {
            var o = OpenDrtSettings().withLook(c.look)
            if (c.tonescale > 0) o = o.withTonescale(c.tonescale - 1)
            val s = JpegOutputSettings(toneMapper = PhotoToneMapper.OPENDRT, toneLook = ToneLookSettings(openDrt = o))
            val u = ToneLook.values(s)
            inputs.forEachIndexed { i, rgb ->
                val got = OpenDrt.map(rgb, u, c.p3)
                for (ch in 0..2) assertEquals("look ${c.look} ts ${c.tonescale} p3 ${c.p3} in $i ch $ch",
                    c.expected[i * 3 + ch], oetf(got[ch]), 2e-4f)
            }
        }
    }

    @Test fun presetsAndPrefsRoundTrip() {
        assertEquals(OpenDrtParam.entries.size, OpenDrtSettings().values.size)
        for (i in OpenDrt.LOOKS.indices) assertEquals(OpenDrt.LOOKS[i].second.size + 3, OpenDrt.preset(i).size)
        assertEquals(24 * 4, ToneLook.values(JpegOutputSettings()).size)
        val grey = OpenDrt.map(floatArrayOf(.18f, .18f, .18f), ToneLook.values(JpegOutputSettings(toneMapper = PhotoToneMapper.OPENDRT)), false)
        assertTrue(grey[0] > 0.05f && grey[0] < 0.25f)
    }
